AssistantMessageToolRequest(name='create', tool_call_id='function-call-aa843055-873c-4971-b663-122a456d90ed', arguments={'file_text': "document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('contact-form');
    const statusMessage = document.getElementById('status-message');

    form.addEventListener('submit', (e) => {
        e.preventDefault();

        let isValid = true;
        let firstInvalidField = null;

        // Clear previous status message
        statusMessage.textContent = '';

        const fields = [
            { 
                input: document.getElementById('fullName'),
                errorElement: document.getElementById('fullName-error'),
                baseDescribedBy: [],
                validate: (input) => {
                    if (input.value.trim() === '') return 'Error: Full name is required.';
                    return null;
                }
            },
            {
                input: document.getElementById('email'),
                errorElement: document.getElementById('email-error'),
                baseDescribedBy: [],
                validate: (input) => {
                    if (input.value.trim() === '') return 'Error: Email address is required.';
                    if (!input.validity.valid) return 'Error: Enter a valid email address.';
                    return null;
                }
            },
            {
                input: document.getElementById('phone'),
                errorElement: document.getElementById('phone-error'),
                baseDescribedBy: ['phone-help'],
                validate: (input) => {
                    if (input.value.trim() !== '' && !input.validity.valid) {
                        return 'Error: Enter a valid phone number format.';
                    }
                    return null;
                }
            }
        ];

        fields.forEach(field => {
            const errorMsg = field.validate(field.input);
            const describedBy = [...field.baseDescribedBy];

            if (errorMsg) {
                isValid = false;
                field.input.setAttribute('aria-invalid', 'true');
                field.errorElement.textContent = errorMsg;
                field.errorElement.hidden = false;
                describedBy.push(field.errorElement.id);

                if (!firstInvalidField) {
                    firstInvalidField = field.input;
                }
            } else {
                field.input.removeAttribute('aria-invalid');
                field.errorElement.hidden = true;
                field.errorElement.textContent = '';
            }

            if (describedBy.length > 0) {
                field.input.setAttribute('aria-describedby', describedBy.join(' '));
            } else {
                field.input.removeAttribute('aria-describedby');
            }
        });

        if (!isValid) {
            // Focus the first invalid field to aid keyboard and screen reader users
            firstInvalidField.focus();
        } else {
            // Success state handling
            statusMessage.textContent = 'Your message has been sent successfully.';
            form.reset();
        }
    });
});
