const { chromium } = require('playwright');
const axe = require('axe-core');
const fs = require('fs');
const path = require('path');

(async () => {
    let browser;
    try {
        browser = await chromium.launch();
    } catch (e) {
        if (e.message.includes("Executable doesn't exist")) {
            console.error("Browser missing. Need to run playwright install.");
            process.exit(2);
        } else {
            console.error(e);
            process.exit(1);
        }
    }

    try {
        const page = await browser.newPage();
        const htmlContent = fs.readFileSync(path.join(__dirname, 'index.html'), 'utf8');
        await page.setContent(htmlContent, { waitUntil: 'load' });

        // Inject axe-core
        await page.addScriptTag({ content: axe.source });

        const results = await page.evaluate(async () => {
            return await window.axe.run();
        });

        const wcag = results.violations.filter(v => !(v.tags || []).includes('best-practice'));
        const bp = results.violations.filter(v => (v.tags || []).includes('best-practice'));

        console.log(JSON.stringify({
            wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
            bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
        }, null, 2));

        if (wcag.length > 0) {
            process.exit(1);
        }
    } finally {
        if (browser) await browser.close();
    }
})();

